import { readFileSync } from "node:fs";
import { PRODUCTS } from "./data.js";
import { addItem, cartTotal, checkout, removeItem, setQty } from "./cart.js";

// 校验自带 fixtures，与 agent 在 data.js 里填什么商品无关。
const FIXTURE = [
  { id: "a1", name: "Apple", price: 0.5 },
  { id: "b2", name: "Bread", price: 0.2 },
  { id: "c3", name: "Coffee", price: 0.1 },
  { id: "d4", name: "Tea", price: 0.2 },
];

function fail(message) {
  console.error(message);
  process.exit(1);
}

function assert(condition, message) {
  if (!condition) fail(message);
}

function eq(actual, expected, label) {
  if (!Object.is(actual, expected)) {
    fail(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function sameCart(actual, expected, label) {
  eq(JSON.stringify(actual), JSON.stringify(expected), label);
}

function throwsError(fn, pattern, label) {
  try {
    fn();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (pattern.test(message)) return;
    fail(`${label}: expected error matching ${pattern}, got "${message}"`);
  }
  fail(`${label}: expected to throw ${pattern}`);
}

sameCart(addItem([], FIXTURE, "a1"), [{ id: "a1", qty: 1 }], "addItem new item");
sameCart(addItem([{ id: "a1", qty: 1 }], FIXTURE, "a1"), [{ id: "a1", qty: 2 }], "addItem accumulates");
sameCart(addItem([], FIXTURE, "a1", 3), [{ id: "a1", qty: 3 }], "addItem with qty");
throwsError(() => addItem([], FIXTURE, "zz"), /unknown product/, "addItem unknown id");
throwsError(() => addItem([], FIXTURE, "a1", 0), /invalid qty/, "addItem qty 0");
throwsError(() => addItem([], FIXTURE, "a1", -2), /invalid qty/, "addItem negative qty");
throwsError(() => addItem([], FIXTURE, "a1", 1.5), /invalid qty/, "addItem fractional qty");

throwsError(() => setQty([], FIXTURE, "zz", 1), /unknown product/, "setQty unknown id");
sameCart(setQty([{ id: "a1", qty: 1 }], FIXTURE, "a1", 5), [{ id: "a1", qty: 5 }], "setQty updates");
sameCart(setQty([{ id: "a1", qty: 5 }], FIXTURE, "a1", 0), [], "setQty removes at 0");
throwsError(() => setQty([{ id: "a1", qty: 1 }], FIXTURE, "a1", -1), /invalid qty/, "setQty negative");
throwsError(() => setQty([{ id: "a1", qty: 1 }], FIXTURE, "a1", 1.5), /invalid qty/, "setQty fractional");

sameCart(
  removeItem([{ id: "a1", qty: 1 }, { id: "b2", qty: 2 }], "a1"),
  [{ id: "b2", qty: 2 }],
  "removeItem",
);
sameCart(removeItem([{ id: "a1", qty: 1 }], "zz"), [{ id: "a1", qty: 1 }], "removeItem unknown id");

eq(cartTotal([], FIXTURE), 0, "total of empty cart");
eq(cartTotal([{ id: "a1", qty: 2 }, { id: "b2", qty: 1 }], FIXTURE), 1.2, "total sum");
eq(cartTotal([{ id: "c3", qty: 1 }, { id: "b2", qty: 1 }], FIXTURE), 0.3, "total rounds to cents");

const frozenCart = Object.freeze([Object.freeze({ id: "a1", qty: 1 })]);
const grown = addItem(frozenCart, FIXTURE, "b2", 1);
eq(grown.length, 2, "addItem on frozen cart returns a new cart");
eq(frozenCart.length, 1, "frozen cart is unchanged");
eq(frozenCart[0].qty, 1, "frozen item is unchanged");

const receipt = checkout([{ id: "a1", qty: 2 }, { id: "b2", qty: 1 }], FIXTURE, 2);
eq(receipt.total, 1.2, "checkout total");
eq(receipt.change, 0.8, "checkout change");
const rounded = checkout([{ id: "c3", qty: 1 }, { id: "b2", qty: 1 }], FIXTURE, 1);
eq(rounded.total, 0.3, "checkout rounds total to cents");
eq(rounded.change, 0.7, "checkout rounds change to cents");
throwsError(() => checkout([{ id: "a1", qty: 2 }], FIXTURE, 0.5), /insufficient payment/, "checkout underpay");

assert(Array.isArray(PRODUCTS) && PRODUCTS.length >= 4, "PRODUCTS must be an array of at least 4 products");
for (const product of PRODUCTS) {
  assert(typeof product.id === "string" && product.id.length > 0, "each product needs a non-empty string id");
  assert(typeof product.name === "string" && product.name.length > 0, "each product needs a non-empty string name");
  assert(typeof product.price === "number" && product.price > 0, `product ${product.id} needs a positive numeric price`);
}

let html;
try {
  html = readFileSync("index.html", "utf8");
} catch {
  fail("index.html is missing");
}
for (const needle of ["cart.js", "data.js", 'id="product-list"', 'id="cart"', 'id="total"']) {
  assert(html.includes(needle), `index.html must contain ${needle}`);
}

console.log("pos ok");
